use std::fs::File;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::Command;

use anyhow::{bail, Context, Result};
use flate2::read::GzDecoder;

use crate::modules::Module;

/// PID 1 inside the guest. The root filesystem is mounted read-only, so scratch dirs are tmpfs.
const INIT: &str = r#"#!/bin/sh
# moniqi guest init (generated by moniqi-image)
export PATH=/usr/sbin:/usr/bin:/sbin:/bin
mount -t proc proc /proc
mount -t sysfs sys /sys
mount -t devtmpfs dev /dev 2>/dev/null
mkdir -p /dev/pts /dev/shm
mount -t devpts devpts /dev/pts
for d in /run /tmp /var/tmp /var/log /var/lib; do mount -t tmpfs tmpfs "$d" 2>/dev/null; done

echo "moniqi: shell fallback init ($(uname -r))" > /dev/hvc0
# ubuntu-base ships neither kmod nor iproute2, so this fallback cannot load binder_linux.
# Build with BuildOptions::guest_init (the Rust PID 1) for a working guest.
if command -v insmod >/dev/null 2>&1; then
    while read -r m; do
        [ -n "$m" ] && { insmod "/lib/moniqi/modules/$m.ko" 2>/dev/hvc0 || echo "moniqi: insmod $m failed" > /dev/hvc0; }
    done < /lib/moniqi/modules.load
else
    echo "moniqi: insmod missing; kernel modules NOT loaded" > /dev/hvc0
fi

# binderfs gives redroid its own binder devices (needs binder_linux loaded or built in).
mkdir -p /dev/binderfs
mount -t binder binder /dev/binderfs 2>/dev/hvc0 || echo "moniqi: binderfs unavailable" > /dev/hvc0

# zram swap: compress cold guest pages instead of growing host memory.
if [ -e /sys/block/zram0 ]; then
    echo zstd > /sys/block/zram0/comp_algorithm 2>/dev/null
    echo 1G > /sys/block/zram0/disksize && mkswap /dev/zram0 >/dev/null && swapon -p 100 /dev/zram0
fi

hostname moniqi
command -v ip >/dev/null 2>&1 && { ip link set lo up; ip link set eth0 up; }

echo "moniqi: boot ok" > /dev/hvc0
if [ -x /usr/local/bin/moniqi-agent ]; then
    exec /usr/local/bin/moniqi-agent
fi
echo "moniqi: no guest agent installed; idling" > /dev/hvc0
exec sleep infinity
"#;

/// Locate `mke2fs` (Homebrew's e2fsprogs is keg-only, so it is usually not on PATH).
pub fn find_mke2fs() -> Option<PathBuf> {
    let candidates = [
        "/opt/homebrew/opt/e2fsprogs/sbin/mke2fs",
        "/usr/local/opt/e2fsprogs/sbin/mke2fs",
        "/opt/homebrew/sbin/mke2fs",
    ];
    if let Some(p) = candidates.iter().map(PathBuf::from).find(|p| p.exists()) {
        return Some(p);
    }
    std::env::var_os("PATH").and_then(|paths| {
        std::env::split_paths(&paths).map(|d| d.join("mke2fs")).find(|p| p.exists())
    })
}

/// Rewrite `base_tar_gz` into an uncompressed tar with moniqi's files added.
/// Entries we override are dropped from the base so the result has no duplicates.
///
/// ubuntu-base is usr-merged (`/lib -> usr/lib`, `/sbin -> usr/sbin`), so everything is written
/// under `usr/` to avoid replacing those symlinks with directories. `guest_init`, when given,
/// is a static aarch64 binary installed as PID 1 instead of the shell fallback.
pub fn overlay_tar(
    base_tar_gz: &Path,
    modules: &[Module],
    guest_init: Option<&[u8]>,
    guest_agent: Option<&[u8]>,
    scrcpy_server: Option<&[u8]>,
    out_tar: &Path,
) -> Result<()> {
    let mut extra: Vec<(String, Vec<u8>, u32)> = Vec::new();
    let init = guest_init.unwrap_or(INIT.as_bytes());
    extra.push(("usr/sbin/moniqi-init".into(), init.to_vec(), 0o755));
    if let Some(agent) = guest_agent {
        extra.push(("usr/local/bin/moniqi-agent".into(), agent.to_vec(), 0o755));
    }
    if let Some(jar) = scrcpy_server {
        extra.push(("usr/lib/moniqi/scrcpy-server.jar".into(), jar.to_vec(), 0o644));
    }
    let load: String = modules.iter().map(|m| format!("{}\n", m.name)).collect();
    extra.push(("usr/lib/moniqi/modules.load".into(), load.into_bytes(), 0o644));
    for m in modules {
        extra.push((format!("usr/lib/moniqi/modules/{}.ko", m.name), m.data.clone(), 0o644));
    }
    let overridden: Vec<String> = extra.iter().map(|(p, _, _)| p.clone()).collect();

    let src = File::open(base_tar_gz).with_context(|| format!("open {}", base_tar_gz.display()))?;
    let mut input = tar::Archive::new(GzDecoder::new(src));
    let mut out = tar::Builder::new(File::create(out_tar)?);

    let mut base_dirs = std::collections::BTreeSet::new();
    for e in input.entries()? {
        let mut e = e?;
        let path = e.path()?.to_string_lossy().trim_start_matches("./").trim_end_matches('/').to_string();
        if path.is_empty() || overridden.iter().any(|o| *o == path) {
            continue;
        }
        if e.header().entry_type().is_dir() {
            base_dirs.insert(path.clone());
        }
        let mut header = e.header().clone();
        match header.entry_type() {
            t if t.is_symlink() || t.is_hard_link() => {
                let target = e.link_name()?.context("link without target")?.into_owned();
                out.append_link(&mut header, &path, target)?;
            }
            _ => out.append_data(&mut header, &path, &mut e)?,
        }
    }

    let mut dirs_added = base_dirs; // never re-emit a directory the base already has
    for (path, data, mode) in &extra {
        for anc in Path::new(path).ancestors().skip(1).filter(|a| !a.as_os_str().is_empty()) {
            let a = anc.to_string_lossy().to_string();
            if dirs_added.insert(a.clone()) {
                let mut h = tar::Header::new_gnu();
                h.set_entry_type(tar::EntryType::Directory);
                h.set_mode(0o755);
                h.set_uid(0);
                h.set_gid(0);
                h.set_size(0);
                out.append_data(&mut h, format!("{a}/"), std::io::empty())?;
            }
        }
        let mut h = tar::Header::new_gnu();
        h.set_mode(*mode);
        h.set_uid(0);
        h.set_gid(0);
        h.set_size(data.len() as u64);
        out.append_data(&mut h, path, &data[..])?;
    }
    out.into_inner()?.flush()?;
    Ok(())
}

/// Build an ext4 image from `tar_path` without root.
///
/// Fast path: `mke2fs -d <tar>` (needs e2fsprogs built with libarchive, which Homebrew's is not).
/// Fallback: create an empty filesystem, then feed `debugfs -w` a script that creates every
/// entry with explicit mode/uid/gid. That never touches a host directory, so macOS's
/// case-insensitive filesystem and non-root ownership cannot corrupt the result.
pub fn make_ext4(tar_path: &Path, img: &Path, size_mib: u64) -> Result<()> {
    let mke2fs = find_mke2fs().context(
        "mke2fs not found. Install it with `brew install e2fsprogs` (keg-only; no PATH change needed)",
    )?;
    let new_image = || -> Result<()> {
        if img.exists() {
            std::fs::remove_file(img)?;
        }
        File::create(img)?.set_len(size_mib << 20)?;
        Ok(())
    };
    let base_args = ["-q", "-t", "ext4", "-m", "0", "-O", "^has_journal", "-L", "moniqi-root", "-E", "root_owner=0:0"];

    new_image()?;
    let out = Command::new(&mke2fs).args(base_args).arg("-d").arg(tar_path).arg(img).output()
        .with_context(|| format!("run {}", mke2fs.display()))?;
    if out.status.success() {
        return Ok(());
    }
    let err = String::from_utf8_lossy(&out.stderr).to_string();
    if !err.contains("libarchive") {
        std::fs::remove_file(img).ok();
        bail!("mke2fs failed ({}): {}", mke2fs.display(), err.trim());
    }

    eprintln!("      mke2fs has no tar support; populating with debugfs");
    new_image()?;
    let out = Command::new(&mke2fs).args(base_args).arg(img).output()?;
    if !out.status.success() {
        std::fs::remove_file(img).ok();
        bail!("mke2fs failed: {}", String::from_utf8_lossy(&out.stderr).trim());
    }
    let debugfs = mke2fs.with_file_name("debugfs");
    if !debugfs.exists() {
        bail!("debugfs not found next to {}", mke2fs.display());
    }
    populate_with_debugfs(&debugfs, tar_path, img).inspect_err(|_| {
        std::fs::remove_file(img).ok();
    })
}

fn populate_with_debugfs(debugfs: &Path, tar_path: &Path, img: &Path) -> Result<()> {
    use std::fmt::Write as _;

    let stage = img.with_extension("stage");
    let _ = std::fs::remove_dir_all(&stage);
    std::fs::create_dir_all(&stage)?;

    let mut script = String::new();
    let mut ar = tar::Archive::new(File::open(tar_path)?);
    let mut skipped = 0usize;
    for (idx, entry) in ar.entries()?.enumerate() {
        let mut e = entry?;
        let raw = e.path()?.to_string_lossy().to_string();
        let path = format!("/{}", raw.trim_start_matches("./").trim_end_matches('/'));
        if path == "/" {
            continue;
        }
        if path.bytes().any(|b| b.is_ascii_whitespace() || b == b'"') {
            skipped += 1; // debugfs's command parser can't express these
            continue;
        }
        let h = e.header();
        let (mode, uid, gid) = (h.mode()? & 0o7777, h.uid()?, h.gid()?);
        let ty = h.entry_type();
        if ty.is_dir() {
            // mke2fs already created /lost+found; everything else must be new.
            if path != "/lost+found" {
                writeln!(script, "mkdir {path}")?;
            }
            writeln!(script, "sif {path} mode 0{:o}", 0o040000 | mode)?;
        } else if ty.is_symlink() {
            let target = e.link_name()?.context("symlink without target")?.to_string_lossy().to_string();
            if target.bytes().any(|b| b.is_ascii_whitespace() || b == b'"') {
                skipped += 1;
                continue;
            }
            writeln!(script, "symlink {path} {target}")?;
        } else if ty.is_file() || ty.is_hard_link() {
            // Hard links become copies: debugfs `ln` doesn't maintain link counts.
            let src = stage.join(idx.to_string());
            if ty.is_hard_link() {
                let target = e.link_name()?.context("hardlink without target")?;
                let t = format!("/{}", target.to_string_lossy().trim_start_matches("./"));
                writeln!(script, "dump {t} {}", src.display())?;
                // Resolved lazily at run time: the link target was written earlier in the script.
                // `dump` reads from the image being built, then we write it back to the new path.
            } else {
                let mut f = File::create(&src)?;
                std::io::copy(&mut e, &mut f)?;
            }
            writeln!(script, "write {} {path}", src.display())?;
            writeln!(script, "sif {path} mode 0{:o}", 0o100000 | mode)?;
        } else {
            skipped += 1; // device nodes, fifos: none in ubuntu-base
            continue;
        }
        writeln!(script, "sif {path} uid {uid}")?;
        writeln!(script, "sif {path} gid {gid}")?;
    }

    let script_path = stage.join("script");
    std::fs::write(&script_path, &script)?;
    let out = Command::new(debugfs).arg("-w").arg("-f").arg(&script_path).arg(img).output()?;
    let text = format!("{}{}", String::from_utf8_lossy(&out.stdout), String::from_utf8_lossy(&out.stderr));
    let problems: Vec<&str> = text
        .lines()
        .filter(|l| {
            let l = l.trim();
            !l.is_empty() && !l.starts_with("debugfs:") && !l.starts_with("Allocated inode:") && !l.starts_with("debugfs ")
        })
        .collect();
    let _ = std::fs::remove_dir_all(&stage);
    if !out.status.success() || !problems.is_empty() {
        bail!(
            "debugfs reported {} problem(s), first: {}",
            problems.len(),
            problems.iter().take(5).copied().collect::<Vec<_>>().join(" | ")
        );
    }
    if skipped > 0 {
        eprintln!("      note: skipped {skipped} unsupported entries");
    }
    Ok(())
}
